<?php
declare(strict_types=1);
$route=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH);
$host=strtolower(explode(':',$_SERVER['HTTP_HOST'])[0]);
if(!in_array($host,['velqnutrition.com','www.velqnutrition.com'],true))header('X-Robots-Tag: noindex, nofollow');
header('X-Content-Type-Options: nosniff');
header('Referrer-Policy: strict-origin-when-cross-origin');
header("Content-Security-Policy: default-src 'self'; img-src 'self' data: https://www.facebook.com https://analytics.tiktok.com; style-src 'self'; script-src 'self' https://www.googletagmanager.com https://connect.facebook.net https://analytics.tiktok.com; connect-src 'self' https://www.google-analytics.com https://analytics.google.com https://region1.google-analytics.com https://www.facebook.com https://analytics.tiktok.com; form-action 'self' https://qusbk4-9s.myshopify.com; frame-ancestors 'none'; base-uri 'self'");
if($route!=='/api/waitlist' && $route!=='/analytics-config.js'){
 if(!in_array($_SERVER['REQUEST_METHOD'],['GET','HEAD'],true)){http_response_code(405);exit;}
 if($route==='/blogs/journal'||str_starts_with($route,'/blogs/journal/')){header('Location: '.str_replace('/blogs/journal','/blog',$_SERVER['REQUEST_URI']),true,301);exit;}
 if(str_starts_with($route,'/blog')&&str_ends_with($route,'/')){header('Location: '.rtrim($route,'/').(isset($_SERVER['QUERY_STRING'])&&$_SERVER['QUERY_STRING']!==''?'?'.$_SERVER['QUERY_STRING']:''),true,301);exit;}
 $assets=json_decode(base64_decode(''),true);
 $path=$route==='/'?'/index.html':$route;
 if(isset($assets[$path.'/index.html']))$path.='/index.html';
 if(!isset($assets[$path])){http_response_code(404);header('Content-Type: text/plain; charset=utf-8');echo 'Not found';exit;}
 header('Content-Type: '.$assets[$path]['type']);
 header('Cache-Control: '.(str_starts_with($path,'/assets/')?'public, max-age=86400':'no-cache'));
 if($_SERVER['REQUEST_METHOD']!=='HEAD')echo base64_decode($assets[$path]['data']);exit;
}
$upstream = 'https://velq-daily-mock.josephvelasquez604.chatgpt.site';
$path = parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH);
$analytics = str_ends_with($path, '/analytics-config.js');
function fail(int $status, string $message): never {
    http_response_code($status);
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode(['error' => $message]);
    exit;
}
if ($analytics) {
    if (!in_array($_SERVER['REQUEST_METHOD'], ['GET', 'HEAD'], true)) fail(405, 'Method not allowed.');
} else {
    if ($_SERVER['REQUEST_METHOD'] !== 'POST') fail(405, 'Method not allowed.');
    $origin = parse_url($_SERVER['HTTP_ORIGIN'] ?? '');
    $host = strtolower(explode(':', $_SERVER['HTTP_HOST'])[0]);
    if (($origin['scheme'] ?? '') !== 'https' || strtolower($origin['host'] ?? '') !== $host || isset($origin['port'])) fail(403, 'Please join through the Velq website.');
    if (!str_starts_with($_SERVER['CONTENT_TYPE'] ?? '', 'application/json')) fail(415, 'Invalid request format.');
    $body = file_get_contents('php://input', false, null, 0, 2049);
    if ($body === false || strlen($body) > 2048) fail(400, 'Please check your information and try again.');
}
if (!function_exists('curl_init')) fail(503, 'Signup service unavailable.');
$curl = curl_init($upstream . ($analytics ? '/analytics-config.js' : '/api/waitlist'));
curl_setopt_array($curl, [CURLOPT_RETURNTRANSFER => true, CURLOPT_FOLLOWLOCATION => false, CURLOPT_CONNECTTIMEOUT => 4, CURLOPT_TIMEOUT => 13, CURLOPT_SSL_VERIFYPEER => true, CURLOPT_SSL_VERIFYHOST => 2]);
if (!$analytics) curl_setopt_array($curl, [CURLOPT_POST => true, CURLOPT_POSTFIELDS => $body, CURLOPT_HTTPHEADER => ['Content-Type: application/json', 'Origin: ' . $upstream]]);
$response = curl_exec($curl);
$status = curl_getinfo($curl, CURLINFO_HTTP_CODE);
curl_close($curl);
if ($response === false || $status < 200 || $status >= 500) fail(503, 'We couldn’t save your signup right now. Please try again shortly.');
if (!$analytics && json_decode($response, true) === null) fail(503, 'Signup service unavailable.');
http_response_code($status);
header('Content-Type: ' . ($analytics ? 'text/javascript' : 'application/json') . '; charset=utf-8');
if ($_SERVER['REQUEST_METHOD'] !== 'HEAD') echo $response;
